// catalog · кейс cat-21 (.qa/tests/catalog/) — #618f738e (עבר QA 2026-10-07): в форме товара вариант «בלי קטגוריה» = «— ללא קטגוריה —»
// (value "", выбран по умолчанию); в форме категории «קטגוריית אב» остаётся «— ללא (קטגוריה ראשית) —».
// describe 1 — только чтение (@prod-safe): формы открываются и закрываются «ביטול», ничего не сохраняется.
// describe 2 — создаёт свой товар «QA-AUTO-nocat-<ts>» без категории; afterAll удаляет его. Реальные товары/категории не трогаются.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

const ADMIN = path.resolve(__dirname, '../../../auth/admin.json');
test.use({ storageState: ADMIN });

const NO_CATEGORY = '— ללא קטגוריה —'; // U+2014 по краям
const ROOT_PARENT = '— ללא (קטגוריה ראשית) —';

const categorySelect = (page: Page) => page.getByRole('combobox', { name: 'קטגוריה' });

async function expectNoCategoryFirst(page: Page) {
  const cb = categorySelect(page);
  await expect(cb).toBeVisible({ timeout: 20_000 });
  const first = cb.locator('option').first();
  await expect(first).toHaveText(NO_CATEGORY);
  await expect(first).toHaveAttribute('value', '');
  await expect(cb.locator('option', { hasText: 'קטגוריה ראשית' })).toHaveCount(0);
}

test.describe('catalog — טופס מוצר: «— ללא קטגוריה —» (#618f738e)', () => {
  test('מוצר חדש: האפשרות הראשונה ב«קטגוריה» — «— ללא קטגוריה —», נבחרת כברירת מחדל #618f738e @desktop @prod-safe', async ({ page }) => {
    await page.goto('/catalog/new');
    await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible({ timeout: 20_000 });
    await expectNoCategoryFirst(page);
    await expect(categorySelect(page)).toHaveValue('');
    await page.getByRole('button', { name: 'ביטול', exact: true }).click(); // ничего не сохраняем
  });

  test('עריכת מוצר קיים: האפשרות הראשונה ב«קטגוריה» — «— ללא קטגוריה —» #618f738e @desktop @prod-safe', async ({ page }) => {
    await page.goto('/catalog');
    await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible();
    const minCell = page.getByRole('button', { name: /^עדכון רף מינימום — / }).first();
    await expect(minCell).toBeVisible({ timeout: 20_000 });
    const name = (await minCell.getAttribute('aria-label'))!.replace(/^עדכון רף מינימום — /, '');
    await page.getByRole('button', { name, exact: true }).first().click();
    await expect(page).toHaveURL(/\/catalog\/[0-9a-f-]{36}\/edit$/);
    await expectNoCategoryFirst(page);
    await page.getByRole('button', { name: 'ביטול', exact: true }).click(); // ничего не сохраняем
  });

  test('טופס קטגוריה: «קטגוריית אב» בלי שינוי — «— ללא (קטגוריה ראשית) —» #618f738e @desktop @prod-safe', async ({ page }) => {
    await page.goto('/catalog/categories');
    await expect(page.getByRole('heading', { level: 1, name: 'קטגוריות' })).toBeVisible({ timeout: 20_000 });
    await page.getByRole('button', { name: 'קטגוריה חדשה' }).click();
    const parent = page.getByRole('combobox', { name: 'קטגוריית אב' });
    await expect(parent).toBeVisible();
    const first = parent.locator('option').first();
    await expect(first).toHaveText(ROOT_PARENT);
    await expect(first).toHaveAttribute('value', '');
    await expect(parent.locator('option', { hasText: NO_CATEGORY })).toHaveCount(0);
    await page.getByRole('button', { name: 'ביטול', exact: true }).click(); // ничего не сохраняем
  });
});

test.describe('catalog — מוצר בלי קטגוריה נשמר, ברשימה «—» (#618f738e, QA-AUTO)', () => {
  test.describe.configure({ mode: 'serial' });
  const TS = Date.now().toString().slice(-7);
  const P = `QA-AUTO-nocat-${TS}`;
  const SKU = `QA-AUTO-NOCAT-${TS}`;
  let productId = '';

  const rowOf = (page: Page) =>
    page.getByRole('button', { name: P, exact: true }).locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]');

  async function search(page: Page) {
    await page.goto('/catalog');
    await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 20_000 });
    await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(P);
    await expect(page.getByRole('button', { name: P, exact: true }).or(page.getByText('לא נמצאו מוצרים התואמים לסינון'))).toBeVisible({ timeout: 20_000 });
  }

  test.afterAll(async ({ browser }) => {
    const ctx = await browser.newContext({ storageState: ADMIN, locale: 'he-IL' });
    const page = await ctx.newPage();
    try {
      await search(page);
      if (!(await page.getByRole('button', { name: P, exact: true }).count())) return;
      await rowOf(page).getByRole('button', { name: 'פעולות' }).click();
      await page.getByRole('menuitem', { name: /^מחיקה/ }).click();
      const dlg = page.getByRole('dialog');
      await expect(dlg.getByRole('heading', { name: 'מחיקת מוצר' })).toBeVisible();
      await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
      await expect(page.getByText(/נמחק\.|הוסר מהקטלוג/).first()).toBeVisible({ timeout: 15_000 });
    } finally {
      await ctx.close();
    }
  });

  test('יצירת מוצר בלי לגעת ב«קטגוריה» → נשמר; ברשימה עמודת «קטגוריה» = «—»; בעריכה נבחר «— ללא קטגוריה —» #618f738e @desktop', async ({ page }) => {
    await page.goto('/catalog/new');
    await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible({ timeout: 20_000 });
    await expect(categorySelect(page)).toHaveValue('');
    await page.getByRole('textbox', { name: /שם מוצר/ }).fill(P);
    await page.getByRole('textbox', { name: /מק"ט/ }).fill(SKU);
    await page.getByRole('spinbutton', { name: 'מחיר בסיס' }).fill('1');
    await page.getByRole('button', { name: 'שמירה', exact: true }).click();
    await expect(page.getByText('נוסף לקטלוג.')).toBeVisible({ timeout: 15_000 });

    await search(page);
    // колонки строки по порядку: תמונה · שם מוצר · קטגוריה · מק"ט — после имени сразу «—», затем מק"ט
    // (селектор по порядку колонок записан по скриншоту 618f738e-3-catalog-row; при падении на этой строке — сверить healer'ом)
    await expect(rowOf(page)).toHaveText(new RegExp(`${P}\\s*—\\s*QA-AUTO`), { timeout: 20_000 });
    await expect(rowOf(page)).not.toContainText('קטגוריה ראשית');

    await page.getByRole('button', { name: P, exact: true }).click();
    await expect(page).toHaveURL(/\/edit$/);
    productId = page.url().match(/catalog\/([0-9a-f-]{36})\/edit/)![1];
    await page.reload();
    await expectNoCategoryFirst(page);
    await expect(categorySelect(page)).toHaveValue('');
    await expect(categorySelect(page).locator('option:checked')).toHaveText(NO_CATEGORY);
    expect(productId).toBeTruthy();
  });
});
